/// Result of routing one task through the Instella MoE team router.
#[derive(Debug, Clone)]
pub struct TeamRoute {
    pub team: &'static str,
    pub lead: &'static str,
    pub confidence: f64,
    pub score: usize,
    /// What the leader was compared against. A score means nothing without the runner-up.
    pub runner_up: usize,
    /// True when no team matched: the default is a coordination fallback, not a decision, and its
    /// confidence is 0. It used to be 0.2, from a score the router invented to fill the field.
    pub defaulted: bool,
    /// The same numbers as the report text, so the choice can be audited without re-running it.
    pub basis: String,
}

/// Route a task to the single best expert team (mirrors InstellaSingleExpertRouter.route).
///
/// The confidence is derived from the evidence rather than a saturating divisor: it is the share of
/// this team's matched domains that **no other team matched**. The previous `min(score/5, 1.0)` could
/// not tell "5 domains, rival at 4" from "5 domains, rival at 0" -- both scored 1.00 -- and a task
/// matching nothing was given an invented score of 1 (confidence 0.20) by the fallback arm.
pub fn route(task: &str) -> TeamRoute {
    let t = task.to_lowercase();
    let mut scored: Vec<(&'static str, &'static str, usize)> = TEAMS
        .iter()
        .map(|(team, lead, domains)| {
            (*team, *lead, domains.iter().filter(|d| t.contains(**d)).count())
        })
        .collect();
    // Deterministic on ties: by score, then by team name, so the same input always routes the same
    // way regardless of the order TEAMS happens to be declared in.
    scored.sort_by(|a, b| b.2.cmp(&a.2).then(a.0.cmp(b.0)));

    let (team, lead, score) = scored[0];
    let runner_up = scored.get(1).map(|x| x.2).unwrap_or(0);
    if score == 0 {
        return TeamRoute {
            team: "Operations",
            lead: "Orchestra",
            confidence: 0.0,
            score: 0,
            runner_up: 0,
            defaulted: true,
            basis: "no team matched any domain keyword: Operations is the coordination fallback, confidence 0".to_string(),
        };
    }
    let unique = score.saturating_sub(runner_up);
    let confidence = (unique as f64) / (score as f64);
    TeamRoute {
        team,
        lead,
        confidence,
        score,
        runner_up,
        defaulted: false,
        basis: format!(
            "{score} domains matched, runner-up {runner_up} ({unique} unique to this team) -> confidence {unique}/{score}"
        ),
    }
}

/// Unified routing (MOTION-036): consult the swarm council's own router (`swarm_intel::route`) FIRST —
/// this is the SAME 14-agent routing the council votes with, closing the seam between the chat and the
/// council. When the council matches an agent (overlap > 0) whose name is a TEAMS lead, that agent's
/// team + lead are used; otherwise fall back to the keyword router below. Agents the council knows that
/// are not TEAMS leads (e.g. Hermes, Seeker, THzGateway) fall through to the keyword router until the
/// TEAMS table is widened to carry them.
pub fn unified_route(task: &str) -> TeamRoute {
    let (agent, overlap) = swarm_intel::route(task);
    if overlap > 0 {
        if let Some(&(team, lead, _)) = TEAMS.iter().find(|(_, l, _)| *l == agent) {
            return TeamRoute {
                team,
                lead,
                confidence: 1.0,
                score: overlap,
                runner_up: 0,
                defaulted: false,
                basis: format!(
                    "swarm_intel::route -> {agent} (overlap {overlap}) — the council's own routing, no rival computed"
                ),
            };
        }
    }
    route(task)
}

/// The experts the platform carries, as a live routing table + a measured routing-performance
/// sample. Every council agent is now a routable team (15/15), so a task can reach any expert;
/// the latency is measured on the CPU (one route() call over all teams), not asserted.
pub fn experts_payload() -> serde_json::Value {
    let teams: Vec<serde_json::Value> = TEAMS
        .iter()
        .map(|(team, lead, domains)| {
            serde_json::json!({ "team": team, "lead": lead, "domains": domains })
        })
        .collect();
    let start = std::time::Instant::now();
    let sample = route("prove a k3 kleene theorem");
    let latency_ns = start.elapsed().as_nanos();
    serde_json::json!({
        "router": "Instella MoE single-expert router (CPU, keyword-exclusive confidence)",
        "total_teams": TEAMS.len(),
        "experts_carried": TEAMS.len(),
        "routing_latency_ns": latency_ns,
        "routing_latency_basis": "measured: one route() over all teams, no model involved",
        "sample_route": {
            "task": "prove a k3 kleene theorem",
            "team": sample.team,
            "lead": sample.lead,
            "confidence": sample.confidence,
            "runner_up": sample.runner_up,
            "defaulted": sample.defaulted,
        },
        "teams": teams,
    })
}

